async function eventSchema(db){
 await db.prepare("CREATE TABLE IF NOT EXISTS fp_daily_events (day INTEGER PRIMARY KEY, payload TEXT NOT NULL, updated INTEGER NOT NULL)").run();
 const existing=await db.prepare("SELECT day FROM fp_daily_events WHERE day BETWEEN 1 AND 12").all();
 const seen=new Set(existing.results.map(r=>r.day));
 const pending=eventSeed.map((s,i)=>({day:i+1,events:Object.fromEntries(s.split(" ").map(t=>{const [id,v]=t.split(":");return [id,[...v].map(Number)]}))})).filter(r=>!seen.has(r.day));
 if(pending.length)await db.batch(pending.map(r=>db.prepare("INSERT OR IGNORE INTO fp_daily_events VALUES (?,?,?)").bind(r.day,JSON.stringify(r.events),Date.now())));
}
async function statisticsApi(req,db){const u=await permissions(db,await session(req,db));if(!u||!(u.level===3||u.views.includes("statistiche")))return json({error:"Non autorizzato"},403);if(req.method!=="GET")return json({error:"Metodo non consentito"},405);
await db.batch([db.prepare("CREATE TABLE IF NOT EXISTS fp_roster_snapshot (id INTEGER PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL, updated INTEGER NOT NULL)"),db.prepare("CREATE TABLE IF NOT EXISTS fp_daily_stats (id INTEGER PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL, updated INTEGER NOT NULL)")]);await eventSchema(db);
const [r,d,e]=await Promise.all([db.prepare("SELECT payload FROM fp_roster_snapshot WHERE id=1").first(),db.prepare("SELECT payload FROM fp_daily_stats WHERE id=1").first(),db.prepare("SELECT day,payload FROM fp_daily_events ORDER BY day").all()]);if(!r)return json({players:[],through:null,eventThrough:0});const base=JSON.parse(r.payload),daily=d?JSON.parse(d.payload):null,map=new Map((daily?.players||[]).map(p=>[p.id,p.history])),events=new Map(e.results.map(r=>[r.day,JSON.parse(r.payload)]));let eventThrough=0;while(events.has(eventThrough+1))eventThrough++;return json({through:daily?.through||11,eventThrough,players:base.players.map(p=>({id:p.id,name:p.name,owner:p.owner,role:p.role,team:p.team,goals:p.goals,assists:p.assists,conceded:p.conceded,fm:p.fm,history:map.get(p.id)||null,events:Array.from({length:eventThrough},(_,i)=>events.get(i+1)[p.id]||[0,0,0])}))})}

const hallSeed=[[1993,"Marco",null,null],[1994,"Andrea",null,null],[1995,"Michele",null,null],[1996,"Roberto",null,null],[1997,"Fabio",null,null],[1998,"Michele",null,null],[1999,"Daniele",null,null],[2000,"Marco",null,null],[2001,"Roberto",null,null],[2002,"Daniele",null,null],[2003,"Michele",null,null],[2004,"Roberto","Giulio",null],[2005,"Roberto",null,null],[2006,"Alfonso","Fabrizio",null],[2007,"Fabrizio","Michele",null],[2008,"Marco","Cepe",null],[2009,"Marco","Daniele","Michele"],[2010,"Daniele","Alfonso","Fabrizio"],[2011,"Daniele","Roberto","Alfonso"],[2012,"Fabrizio","Roberto","Michele"],[2013,"Alfonso","Fabrizio","Michele"],[2014,"Marco","Michele","Alfonso"],[2015,"Daniele","Cepe","Alfonso"],[2016,"Paolo","Michele","Fabrizio"],[2017,"Fabrizio","Paolo","Michele"],[2018,"Marco","Giorgio","Alfonso"],[2019,"Giorgio","Andrea","Alfonso"],[2020,"Roberto","Daniele","Paolo"],[2021,"Daniele","Marco","Andrea"],[2022,"Daniele","Marco","Paolo"],[2023,"Michele","Marco","Alfonso"],[2024,"Cepe","Alfonso","Daniele"],[2025,"Daniele","Paolo","Michele"],[2026,"Daniele","Cepe","Tomaso"]];
async function hallApi(req,db){const u=await permissions(db,await session(req,db));if(!u||!(u.level===3||u.views.includes("albo")))return json({error:"Non autorizzato"},403);await db.prepare("CREATE TABLE IF NOT EXISTS fp_hall (year INTEGER PRIMARY KEY, gold TEXT, silver TEXT, bronze TEXT, updated INTEGER, actor TEXT)").run();const existing=await db.prepare("SELECT year FROM fp_hall").all(),known=new Set(existing.results.map(r=>r.year));const pending=hallSeed.filter(r=>!known.has(r[0]));if(pending.length)await db.batch(pending.map(r=>db.prepare("INSERT OR IGNORE INTO fp_hall(year,gold,silver,bronze) VALUES (?,?,?,?)").bind(...r)));if(req.method==="POST"){if(u.level!==3||req.headers.get("Origin")!==new URL(req.url).origin)return json({error:"Non autorizzato"},403);let b;try{b=await req.json()}catch{return json({error:"Dati non validi"},400)}const vals=[b.gold,b.silver,b.bronze].map(v=>typeof v==="string"?v.trim():null).map(v=>v||null);if(!Number.isInteger(b.year)||b.year<1993||b.year>new Date().getFullYear()+1||vals.some(v=>v&&v.length>40)||new Set(vals.filter(Boolean).map(v=>v.toLowerCase())).size!==vals.filter(Boolean).length)return json({error:"Podio non valido"},400);await db.batch([db.prepare("INSERT INTO fp_hall VALUES (?,?,?,?,?,?) ON CONFLICT(year) DO UPDATE SET gold=excluded.gold,silver=excluded.silver,bronze=excluded.bronze,updated=excluded.updated,actor=excluded.actor").bind(b.year,...vals,Date.now(),u.username),db.prepare("INSERT INTO fp_audit(actor,action,detail,created) VALUES (?,?,?,?)").bind(u.username,"hall_update",JSON.stringify({year:b.year,values:vals}),Date.now())])}else if(req.method!=="GET")return json({error:"Metodo non consentito"},405);const r=await db.prepare("SELECT year,gold,silver,bronze FROM fp_hall ORDER BY year DESC").all();return json({rows:r.results})}
export async function auth(req,env,path){
const db=env.DB;try{await schema(db);await permissionSchema(db);await simpleSchema(db);
if(path==="/api/auth/login-log"){const u=await permissions(db,await session(req,db));if(u?.level!==3||req.method!=="GET")return json({error:"Accesso riservato"},403);const username=new URL(req.url).searchParams.get("username");if(username){const rows=await db.prepare("SELECT level,created FROM fp_login_log WHERE username=? ORDER BY id DESC LIMIT 100").bind(username).all();return json({rows:rows.results})}const rows=await db.prepare("SELECT a.username,a.level,a.enabled,(SELECT COUNT(*) FROM fp_login_log l WHERE l.username=a.username) AS logins,(SELECT MAX(created) FROM fp_login_log l WHERE l.username=a.username) AS last_login,(SELECT updated FROM fp_activity t WHERE t.username=a.username) AS last_activity FROM ("+accountSQL+") a ORDER BY COALESCE(last_activity,last_login,0) DESC,a.username").all();return json({rows:rows.results})}
if(path==='/api/auth/hall')return await hallApi(req,db);
if(path==='/api/auth/statistics')return await statisticsApi(req,db);
if(path==='/api/auth/what-if')return await whatIfApi(req,db);
if(path==='/api/auth/group-photo')return await groupPhoto(req,db);
if(path.startsWith('/api/auth/invite/'))return await inviteApi(req,db,path);
if(path==='/api/auth/results')return await resultsApi(req,db);
if(path.startsWith('/api/auth/formation'))return await formationApi(req,db,path);
if(path==='/api/auth/rosters'||path==='/api/auth/rosters/import'||path==='/api/auth/stats/import')return await rosterApi(req,db,path);
if(['/api/auth/simple-permissions','/api/auth/permissions','/api/auth/visibility','/api/auth/individual-visibility','/api/auth/account','/api/auth/permission-mode','/api/auth/permission-reset','/api/auth/permission-group','/api/auth/collaborator','/api/auth/guest'].includes(path))return await manage(req,db,path);
if(path==="/api/auth/me"&&req.method==="GET"){const u=await permissions(db,await session(req,db));const admin=await db.prepare("SELECT 1 AS present FROM fp_users WHERE role='admin' LIMIT 1").first();let extra={};const t=(req.headers.get("Cookie")||"").match(/(?:^|;\s*)fp_session=([a-f0-9]{64})(?:;|$)/)?.[1];if(u&&t){const hash=await digest(t),now=Date.now();const renewed=await db.prepare("UPDATE fp_sessions SET expires=? WHERE token_hash=? AND username=? AND expires>? AND EXISTS (SELECT 1 FROM fp_remember WHERE token_hash=?)").bind(now+2592000000,hash,u.username,now,hash).run();if(renewed.meta.changes===1)extra={"Set-Cookie":cookie(t,2592000)}}return json({user:u,setup:!admin},200,extra)}
if(req.method!=="POST")return json({error:"Metodo non consentito"},405);
if(req.headers.get("Origin")!==new URL(req.url).origin)return json({error:"Richiesta non consentita"},403);
if(path==="/api/auth/logout"){const t=(req.headers.get("Cookie")||"").match(/(?:^|;\s*)fp_session=([a-f0-9]{64})(?:;|$)/)?.[1];if(t)await db.prepare("DELETE FROM fp_sessions WHERE token_hash=?").bind(await digest(t)).run();return json({ok:true},200,{"Set-Cookie":cookie("",0)})}
if(Number(req.headers.get("Content-Length")||0)>4096)return json({error:"Richiesta troppo grande"},413);
const raw=await req.text();if(raw.length>4096)return json({error:"Richiesta troppo grande"},413);let b;try{b=JSON.parse(raw)}catch{return json({error:"Dati non validi"},400)}
const username=typeof b.username==="string"?b.username.trim().toLowerCase():"";const p=b.password;if(!/^[a-z0-9_-]{2,30}$/.test(username)||typeof p!=="string"||p.length<12||p.length>128)return json({error:"Nome utente o password non validi (minimo 12 caratteri)."},400);
const now=Date.now();const ip=req.headers.get("CF-Connecting-IP")||"unknown";const key=await digest(ip+"|"+username);const a=await db.prepare("INSERT INTO fp_attempts VALUES (?,1,?) ON CONFLICT(key) DO UPDATE SET n=CASE WHEN expires<=? THEN 1 ELSE n+1 END,expires=CASE WHEN expires<=? THEN excluded.expires ELSE expires END RETURNING n").bind(key,now+900000,now,now).first();if(a.n>8)return json({error:"Troppi tentativi. Riprova tra 15 minuti."},429);
let u;
if(path==="/api/auth/setup"){
if(username!=="marco"||typeof b.code!=="string"||!env.ADMIN_SETUP_CODE||env.ADMIN_SETUP_CODE.length<24||!same(await digest(b.code),await digest(env.ADMIN_SETUP_CODE)))return json({error:"Codice di attivazione non valido."},403);
const salt=random(),hash=await derive(p,salt);
const result=await db.prepare("INSERT INTO fp_users (username,salt,password_hash,role) SELECT ?,?,?,'admin' WHERE NOT EXISTS (SELECT 1 FROM fp_users WHERE role='admin')").bind(username,salt,hash).run();if(result.meta.changes!==1)return json({error:"Amministratore già attivato."},409);u={username,role:"admin"};
}else if(path==="/api/auth/login"){const row=await db.prepare("SELECT * FROM fp_users WHERE username=?").bind(username).first();const hash=await derive(p,row?.salt||"invalid-user-placeholder");if(!row||!same(hash,row.password_hash))return json({error:"Credenziali non valide."},401);u={username:row.username,role:row.role};}
else return json({error:"Funzione non disponibile"},404);
u=await permissions(db,u);if(!u)return json({error:"Account disattivato"},403);const t=random(),tokenHash=await digest(t),remember=b.remember==="on"||b.remember===true,age=remember?2592000:86400;await db.batch([db.prepare("DELETE FROM fp_attempts WHERE key=? OR expires<=?").bind(key,now),db.prepare("DELETE FROM fp_sessions WHERE expires<=?").bind(now),db.prepare("DELETE FROM fp_remember WHERE token_hash NOT IN (SELECT token_hash FROM fp_sessions)"),db.prepare("INSERT INTO fp_sessions VALUES (?,?,?)").bind(tokenHash,u.username,now+age*1000),...(remember?[db.prepare("INSERT INTO fp_remember VALUES (?)").bind(tokenHash)]:[]),db.prepare("INSERT INTO fp_login_log(username,level,created) VALUES (?,?,?)").bind(u.username,u.level,now),db.prepare("INSERT INTO fp_activity VALUES (?,?) ON CONFLICT(username) DO UPDATE SET updated=excluded.updated").bind(u.username,now)]);return json({user:u},200,{"Set-Cookie":cookie(t,age)});
}catch(e){return json({error:"Accesso temporaneamente non disponibile."},503)}}
